package luna.tools;

import java.io.BufferedWriter;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileWriter;
import java.io.InputStream;
import java.io.Writer;
import java.util.Properties;

/**
 * Generates the semantic bridge contract consumed by an ASM bridge patcher.
 * The generated file contains no feature logic and no hand-written binary
 * names; those are resolved later from the selected symbol catalog.
 */
public final class LunaBridgeGenerator {

    private LunaBridgeGenerator() { }

    public static void main(String[] args) throws Exception {
        File specFile = new File(args.length > 0 ? args[0] : "tools/luna/bridge-spec.properties");
        File output = new File(args.length > 1 ? args[1]
                : "build/generated/LunaGeneratedBridgeContract.java");
        Properties spec = new Properties();
        InputStream in = new FileInputStream(specFile);
        try {
            spec.load(in);
        } finally {
            in.close();
        }
        File parent = output.getParentFile();
        if (parent != null && !parent.exists() && !parent.mkdirs()) {
            throw new IllegalStateException("cannot create " + parent);
        }
        Writer writer = new BufferedWriter(new FileWriter(output));
        try {
            writer.write("/** Generated by LunaBridgeGenerator. Do not edit. */\n");
            writer.write("public final class LunaGeneratedBridgeContract {\n");
            writer.write("    private LunaGeneratedBridgeContract() { }\n");
            writeConstant(writer, "BASELINE", spec.getProperty("bridge.baseline"));
            writeConstant(writer, "API", spec.getProperty("bridge.api"));
            writeConstant(writer, "LOOKUP_POLICY", spec.getProperty("bridge.lookup"));
            writer.write("}\n");
        } finally {
            writer.close();
        }
        System.out.println("generated=" + output.getPath());
    }

    private static void writeConstant(Writer writer, String name, String value) throws Exception {
        if (value == null) throw new IllegalArgumentException("missing bridge spec: " + name);
        writer.write("    public static final String " + name + " = \"");
        writer.write(value.replace("\\", "\\\\").replace("\"", "\\\""));
        writer.write("\";\n");
    }
}
